import { artifacts } from "hardhat";
import fs from "node:fs";
import path from "node:path";

/** Writes the StakeMarkets ABI as a typed `as const` module for viem consumers. */
async function main() {
  const { abi } = await artifacts.readArtifact("StakeMarkets");
  const source =
    "// Generated by contracts/scripts/export-abi.ts. Do not edit by hand.\n" +
    `export const stakeMarketsAbi = ${JSON.stringify(abi, null, 2)} as const;\n`;

  const root = path.join(__dirname, "..", "..");
  for (const target of ["web/src/lib/abi.ts", "resolver/src/abi.ts"]) {
    const file = path.join(root, target);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, source);
    console.log(`wrote ${target}`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
